3	namespace App\Services\Cache;
4	
5	use App\Jobs\Cache\InvalidateConnectedAffiliateCachesJob;
6	use App\Models\Core\MediaVariant;
7	use App\Models\Core\Professional\BrandPartnerLink;
8	use App\Models\Core\Professional\Professional;
9	use App\Models\Core\Site\Block;
10	use App\Models\Core\Site\Site;
11	use App\Models\Core\Site\SiteSubdomainAlias;
12	use App\Models\Views\PublicSitePayload;
13	use Illuminate\Support\Facades\Cache;
14	use Illuminate\Support\Facades\Log;
15	use Illuminate\Support\Facades\Storage;
16	
17	// V2: Public site payload caching with single-flight locking (prevents thundering herd). Handles 95% of traffic. Simplified in V2 — no more product payload caching.
18	class SiteCacheService
19	{
20	    private const MISS_SENTINEL = '__MISS__';
21	
22	    /** @var array<string, array<string, string|null>|null> */
23	    private array $brandPartnerEnrichmentCache = [];
24	
25	    public function __construct(private readonly CacheLockService $cacheLock) {}
26	
27	    /**
28	     * Query the DB view and build the public site payload, then cache and return it.
29	     * Returns null (with a short-lived sentinel cached) when the subdomain has no
30	     * published site in the view.
31	     *
32	     * @return array<string, mixed>|null
33	     */
34	    protected function buildPayloadFromDb(string $subdomain, string $key): ?array
35	    {
36	        $row = PublicSitePayload::query()
37	            ->whereRaw('lower(subdomain) = ?', [$subdomain])
38	            ->first();
39	
40	        // View only contains published sites; if not found, treat as 404.
41	        if (! $row) {
42	            // Negative-cache briefly to reduce DB load from bot scans.
43	            Cache::put($key, self::MISS_SENTINEL, now()->addSeconds(30));
44	
45	            return null;
46	        }
47	
48	        $payload = $row->payload ?? [];
49	
50	        // The view's COALESCE guarantees services is always a jsonb array,
51	        // so a missing key is the only thing we have to defend against.
52	        $services = $payload['services'] ?? [];
53	
54	        $site = $payload['site'] ?? null;
55	        if (is_array($site)) {
56	            $site = $this->safeHydrateSitePayload(
57	                $site,
58	                (string) ($row->professional_id ?? ''),
59	                (string) ($row->site_id ?? ''),
60	                $subdomain
61	            );
62	        }
63	
64	        // Must match the controller response shape exactly.
65	        $links = is_array($payload['links'] ?? null) ? array_values($payload['links']) : [];
66	        $sections = is_array($payload['sections'] ?? null) ? array_values($payload['sections']) : [];
67	        $existingBlocks = is_array($payload['blocks'] ?? null) ? array_values($payload['blocks']) : [];
68	
69	        $data = [
70	            'published' => true,
71	            'site' => $site,
72	            'professional' => $payload['professional'] ?? null,
73	            'theme' => $payload['theme'] ?? null,
74	            'services' => $services,
75	            'links' => $links,
76	            'sections' => $sections,
77	            'blocks' => $this->buildCombinedBlocksPayload($links, $sections, $existingBlocks),
78	            'legal' => $payload['legal'] ?? null,
79	            // Preserve the store sub-object from the source payload so that
80	            // withStorePayload() below can lift selected_products + commission
81	            // settings out of payload.store. Without this, the rebuilt $data
82	            // has no 'store' key and withStorePayload falls through to empty
83	            // defaults — the front-end would see no featured products even
84	            // though the view row contains them.
85	            'store' => $payload['store'] ?? null,
86	        ];
87	        $data = $this->ensureProfessionalType($data, (string) ($row->professional_id ?? ''));
88	        $data = $this->safeWithStorePayload($data, (string) ($row->professional_id ?? ''), $subdomain);
89	        $data = $this->safeApplyBrandImageFallbacks($data, $subdomain);
90	
91	        Cache::put($key, $data, $this->jitteredPayloadTtl());
92	
93	        return $data;
94	    }
95	
96	    /**
97	     * Returns the public_payload TTL with ±20% jitter applied.
98	     *
99	     * Mirrors CacheLockService::writeWithJitter's distribution so payload-cache
100	     * writes (which use raw Cache::put inside our manual single-flight) get the
101	     * same expiry-spreading behaviour as rememberLocked-managed entries.
102	     */
103	    private function jitteredPayloadTtl(): int
104	    {
105	        return (int) round((int) config('partna.cache.ttls.public_payload') * (0.8 + mt_rand(0, 4000) / 10000.0));
106	    }
107	
108	    /**
109	     * Get public site payload (MOST CRITICAL - 95% of traffic)
110	     *
111	     * IMPORTANT: This must match the PublicSiteController response shape exactly.
112	     */
113	    public function getPublicSitePayload(string $subdomain): ?array
114	    {
115	        $subdomain = strtolower($subdomain);
116	
117	        $key = CacheKeyGenerator::publicSitePayload($subdomain);
118	        $cached = Cache::get($key);
119	
120	        if ($cached === self::MISS_SENTINEL) {
121	            return null;
122	        }
123	        if (is_array($cached)) {
124	            // Backward-compatible cache healing for payload shape changes.
125	            // Older cache entries may not include `services`.
126	            if (array_key_exists('services', $cached)) {
127	                $cached = $this->ensureBlockCollections($cached);
128	                $cached = $this->ensureProfessionalType(
129	                    $cached,
130	                    (string) data_get($cached, 'professional.id', '')
131	                );
132	                $cached = $this->safeWithStorePayload(
133	                    $cached,
134	                    (string) data_get($cached, 'professional.id', ''),
135	                    $subdomain
136	                );
137	
138	                if (! array_key_exists('legal', $cached)) {
139	                    $cached['legal'] = null;
140	                }
141	
142	                // Always resolve image variant paths to URLs (handles pre-URL-resolution cache entries)
143	                $site = $cached['site'] ?? null;
144	                if (is_array($site)) {
145	                    $professionalId = (string) data_get($cached, 'professional.id', '');
146	                    $cached['site'] = $this->safeHydrateSitePayload(
147	                        $site,
148	                        $professionalId,
149	                        '',
150	                        $subdomain
151	                    );
152	                }
153	
154	                Cache::put($key, $cached, $this->jitteredPayloadTtl());
155	
156	                return $cached;
157	            }
158	            Cache::forget($key);
159	        }
160	
161	        // Cache miss — acquire a per-subdomain fill lock so only one process rebuilds
162	        // the payload from the DB view while concurrent requests wait (single-flight).
163	        $fillLock = Cache::lock('site:fill:'.$subdomain, 10);
164	
165	        try {
166	            // Block up to 5 s for the lock; raises LockTimeoutException if it can't.
167	            $fillLock->block(5);
168	        } catch (\Illuminate\Contracts\Cache\LockTimeoutException) {
169	            // Another process is (or was) filling the cache.
170	            $warm = Cache::get($key);
171	            if ($warm === self::MISS_SENTINEL) {
172	                return null;
173	            }
174	            if (is_array($warm)) {
175	                return $warm;
176	            }
177	
178	            // Cache still empty — compute directly rather than flash-404.
179	            // Bounded stampede risk: only requests in the lock-timeout window run this path.
180	            return $this->buildPayloadFromDb($subdomain, $key);
181	        }
182	
183	        try {
184	            // Double-check: the lock winner may have filled the cache while we waited.
185	            $rechecked = Cache::get($key);
186	            if ($rechecked === self::MISS_SENTINEL) {
187	                return null;
188	            }
189	            if (is_array($rechecked) && array_key_exists('services', $rechecked)) {
190	                return $rechecked;
191	            }
192	
193	            return $this->buildPayloadFromDb($subdomain, $key);
194	        } finally {
195	            $fillLock->release();
196	        }
197	    }
198	
199	    /**
200	     * @param  array<string, mixed>  $payload
201	     * @return array<string, mixed>
202	     */
203	    private function applyBrandImageFallbacks(array $payload): array
204	    {
205	        $professional = $payload['professional'] ?? null;
206	        if (! is_array($professional) || ($professional['professional_type'] ?? null) === 'brand') {
207	            return $payload;
208	        }
209	
210	        $affiliateId = (string) ($professional['id'] ?? '');
211	        if (empty($affiliateId)) {
212	            return $payload;
213	        }
214	
215	        // JSON column is affiliate-controlled; use it only as a hint for which brand is configured.
216	        $brandPartner = $payload['site']['settings']['brand_partner'] ?? null;
217	        if (! is_array($brandPartner) || empty($brandPartner['professional_id'])) {
218	            return $payload;
219	        }
220	
221	        $claimedBrandId = (string) $brandPartner['professional_id'];
222	
223	        // BrandPartnerLink is the consent record — verify before using any brand data.
224	        $link = BrandPartnerLink::where('affiliate_professional_id', $affiliateId)
225	            ->where('brand_professional_id', $claimedBrandId)
226	            ->first();
227	
228	        if (! $link) {
229	            Log::warning('Brand-partner enrichment skipped: no verified link in consent table.', [
230	                'affiliate_id' => $affiliateId,
231	                'brand_id' => $claimedBrandId,
232	            ]);
233	
234	            return $payload;
235	        }
236	
237	        // Resolve brand_id from the verified link record, never from the mutable JSON.
238	        $brandId = (string) $link->brand_professional_id;
239	        $brandSite = Site::query()
240	            ->where('professional_id', $brandId)
241	            ->first();
242	
243	        if (! $brandSite) {
244	            return $payload;
245	        }
246	
247	        // Brand placeholders now live in site_media (pool=design, purpose=placeholder).
248	        // The service resolves variant URLs; we project them to { url, alt_text }
249	        // to match the new Hydrogen brand-design response shape.
250	        $designMedia = app(\App\Services\Media\BrandDesignMediaService::class)
251	            ->listDesignMedia((string) $brandSite->id);
252	
253	        if (empty($designMedia['placeholders'])) {
254	            return $payload;
255	        }
256	
257	        $placeholderImages = array_map(
258	            fn (array $p) => [
259	                'url' => $p['url'],
260	                'alt_text' => $p['alt_text'],
261	            ],
262	            $designMedia['placeholders']
263	        );
264	
265	        $imageKeys = ['gallery', 'content_images'];
266	
267	        foreach ($imageKeys as $key) {
268	            if (! isset($payload['site'][$key]) || ! is_array($payload['site'][$key])) {
269	                continue;
270	            }
271	
272	            if (empty($payload['site'][$key])) {
273	                $payload['site'][$key] = $placeholderImages;
274	            }
275	        }
276	
277	        return $payload;
278	    }
