280	    /**
281	     * @param  array<string, mixed>  $site
282	     * @return array<string, mixed>
283	     */
284	    private function safeHydrateSitePayload(array $site, string $professionalId, string $siteId, string $subdomain): array
285	    {
286	        try {
287	            $site = $this->hydrateSiteWithBrandTypography($site, $professionalId);
288	            $site = $this->resolveImageVariantUrlsInSite($site, $siteId);
289	
290	            return $this->enrichSiteWithBrandPartnerRadius($site);
291	        } catch (\Throwable $e) {
292	            Log::warning('Public site payload hydration failed; returning base site payload.', [
