557	    /**
558	     * @param  array<int, mixed>  $links
559	     * @param  array<int, mixed>  $sections
560	     * @param  array<int, mixed>  $existingBlocks
561	     * @return array<int, array<string, mixed>>
562	     */
563	    private function buildCombinedBlocksPayload(array $links, array $sections, array $existingBlocks = []): array
564	    {
565	        if ($links === [] && $sections === []) {
566	            return array_values(array_filter($existingBlocks, fn ($block): bool => is_array($block)));
567	        }
568	
569	        $normalizedLinks = array_map(function ($block): array {
570	            $data = is_array($block) ? $block : [];
571	            $data['block_group'] = 'links';
572	
573	            return $data;
574	        }, $links);
575	
576	        $normalizedSections = array_map(function ($block): array {
577	            $data = is_array($block) ? $block : [];
578	            $data['block_group'] = 'sections';
579	
580	            return $data;
581	        }, $sections);
582	
583	        $combined = array_merge($normalizedLinks, $normalizedSections);
584	
585	        usort($combined, function (array $a, array $b): int {
586	            $aSort = (int) ($a['sort_order'] ?? PHP_INT_MAX);
587	            $bSort = (int) ($b['sort_order'] ?? PHP_INT_MAX);
588	            if ($aSort !== $bSort) {
589	                return $aSort <=> $bSort;
590	            }
591	
592	            $aId = (string) ($a['id'] ?? '');
593	            $bId = (string) ($b['id'] ?? '');
594	
595	            return $aId <=> $bId;
596	        });
597	
598	        return array_values($combined);
599	    }
