660	    /**
661	     * Resolve image variant paths to public URLs in the site payload.
662	     * The view returns storage paths; we need full URLs for the frontend.
663	     * Also resolves video variant/stream/poster paths in gallery_videos and content_videos.
664	     *
665	     * @param  array<string, mixed>  $site
666	     * @return array<string, mixed>
667	     */
668	    private function resolveImageVariantUrlsInSite(array $site, string $siteId): array
669	    {
670	        // --- Collect all media IDs (images + videos) in one pass ---
671	        $allMediaIds = [];
672	        foreach (['gallery', 'content_images', 'gallery_videos', 'content_videos'] as $key) {
673	            foreach ($site[$key] ?? [] as $item) {
674	                if (is_array($item) && ! empty($item['id'])) {
675	                    $allMediaIds[] = $item['id'];
676	                }
677	            }
678	        }
679	
680	        // Single query: one DB round-trip for all variant rows across all media types.
681	        // Index as: media_id → artifact_type → variant_key → URL
682	        $mvByMedia = [];
683	        if ($allMediaIds !== []) {
684	            $allVariants = MediaVariant::query()
685	                ->whereIn('media_id', array_unique($allMediaIds))
686	                ->get();
687	
688	            foreach ($allVariants as $mv) {
689	                $mvByMedia[$mv->media_id][$mv->artifact_type][$mv->variant_key] = $mv->url;
690	            }
691	        }
692	
693	        // --- Images: resolve variant URLs ---
694	        foreach (['gallery', 'content_images'] as $key) {
695	            $items = $site[$key] ?? [];
696	            if (! is_array($items)) {
697	                continue;
698	            }
699	            foreach ($items as $i => $item) {
700	                if (! is_array($item) || empty($item['id'])) {
701	                    continue;
702	                }
703	                $mediaId = $item['id'];
704	                $pathVariants = $item['variants'] ?? [];
705	                if (! is_array($pathVariants)) {
706	                    continue;
707	                }
708	                $urlVariants = [];
709	                foreach ($pathVariants as $variantKey => $path) {
710	                    $url = $mvByMedia[$mediaId]['webp'][$variantKey] ?? null;
711	                    if ($url !== null) {
712	                        $urlVariants[$variantKey] = $url;
713	                    }
714	                }
715	                $site[$key][$i]['variants'] = $urlVariants;
716	            }
717	
718	            usort($site[$key], function ($a, $b) {
719	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
720	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
721	                if ($aSort !== $bSort) {
722	                    return $aSort <=> $bSort;
723	                }
724	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
725	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
726	
727	                return $aId <=> $bId;
728	            });
729	        }
730	
731	        // --- Videos: resolve variant/stream/poster URLs ---
732	        foreach (['gallery_videos', 'content_videos'] as $key) {
733	            $items = $site[$key] ?? [];
734	            if (! is_array($items)) {
735	                continue;
736	            }
737	            foreach ($items as $i => $item) {
738	                if (! is_array($item) || empty($item['id'])) {
739	                    continue;
740	                }
741	                $mediaId = $item['id'];
742	                $byType = $mvByMedia[$mediaId] ?? [];
743	
744	                $site[$key][$i]['variants'] = $byType['mp4'] ?? [];
745	                $site[$key][$i]['streams'] = $byType['hls_playlist'] ?? [];
746	                $site[$key][$i]['poster'] = ($byType['poster']['poster'] ?? null);
747	            }
748	
749	            usort($site[$key], function ($a, $b) {
750	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
751	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
752	                if ($aSort !== $bSort) {
753	                    return $aSort <=> $bSort;
754	                }
755	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
756	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
757	
758	                return $aId <=> $bId;
759	            });
760	        }
761	
762	        // Ensure video keys always exist even when there are no videos (backward-compat).
763	        $site['gallery_videos'] = $site['gallery_videos'] ?? [];
764	        $site['content_videos'] = $site['content_videos'] ?? [];
765	
766	        // --- Document: resolve preview_url from storage path to full CDN URL ---
767	        if (isset($site['document']) && is_array($site['document']) && ! empty($site['document']['preview_url'])) {
768	            $rawPath = (string) $site['document']['preview_url'];
769	            $site['document']['preview_url'] = Storage::disk(config('partna.media_disk'))->url($rawPath);
770	        }
771	
772	        return $site;
773	    }
