799	    /**
800	     * Invalidate all cache keys for a site
801	     */
802	    public function invalidateSite(Site $site): void
803	    {
804	        $professionalId = (string) ($site->professional_id ?? '');
805	
806	        $keys = [
807	            CacheKeyGenerator::publicSitePayload($site->subdomain),
808	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'links')),
809	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'sections')),
810	            CacheKeyGenerator::siteImages($site->id),
811	        ];
812	
813	        // CACHE-1: every (pool, media_type) variant of /api/images. The polling
814	        // path (?ids[]) uses unbounded fingerprint keys and relies on its own 5s
815	        // TTL — not enumerated here.
816	        foreach (CacheKeyGenerator::siteImagesViewVariants() as [$pool, $mediaType]) {
817	            $variantKey = CacheKeyGenerator::siteImagesView($site->id, $pool, $mediaType);
818	            $keys[] = $variantKey;
819	            $keys[] = $variantKey.':stale';
820	        }
821	
822	        // The auth-path Professional model cache (AUTH-1) holds the site relation
823	        // preloaded — site writes must bust it or the next 60s of authenticated
824	        // requests would see a stale subdomain / settings on $pro->site.
825	        if ($professionalId !== '') {
826	            $modelKey = CacheKeyGenerator::professionalModel($professionalId);
827	            $keys[] = $modelKey;
828	            $keys[] = $modelKey.':stale';
829	        }
830	
831	        // If subdomain changed, kill the OLD cache key too.
832	        // This is critical so old URLs redirect (via alias) instead of returning cached payload.
833	        if ($site->wasChanged('subdomain')) {
834	            $old = strtolower((string) $site->getOriginal('subdomain'));
835	            if ($old !== '') {
836	                $keys[] = CacheKeyGenerator::publicSitePayload($old);
837	            }
838	        }
839	
840	        // Invalidate all alias cache keys (your Site model has no aliases() relation)
841	        $aliasSubdomains = SiteSubdomainAlias::query()
842	            ->where('site_id', $site->id)
843	            ->pluck('subdomain')
844	            ->all();
845	
846	        foreach ($aliasSubdomains as $aliasSubdomain) {
847	            $keys[] = CacheKeyGenerator::publicSitePayload(strtolower($aliasSubdomain));
848	        }
849	
850	        Cache::deleteMultiple(array_values(array_unique($keys)));
851	
852	        // CACHE-3: dispatch per-affiliate invalidations with a random 0–30s jitter so
853	        // a brand edit (which may affect hundreds of affiliates) doesn't cold-miss every
854	        // affiliate cache simultaneously and trigger a cache-rebuild stampede.
855	        if ($professionalId !== '') {
856	            $connectedProfessionalIds = BrandPartnerLink::query()
857	                ->where('brand_professional_id', $professionalId)
858	                ->pluck('affiliate_professional_id')
859	                ->all();
860	
861	            $connectedSubdomains = Site::query()
862	                ->whereIn('professional_id', $connectedProfessionalIds)
863	                ->pluck('subdomain')
864	                ->filter(fn ($subdomain): bool => is_string($subdomain) && trim($subdomain) !== '')
865	                ->map(fn ($subdomain): string => strtolower((string) $subdomain))
866	                ->all();
867	
868	            foreach ($connectedSubdomains as $connectedSubdomain) {
869	                InvalidateConnectedAffiliateCachesJob::dispatch($connectedSubdomain)
870	                    ->delay(now()->addSeconds(random_int(0, 30)));
871	            }
872	        }
873	    }
