875	    public function getSiteLinkBlocks(string $siteId): array
876	    {
877	        // Single-flight + ±20% jitter + SWR via CacheLockService. Without the
878	        // lock, a cold cache after a flush lets every concurrent visitor on a
879	        // popular site rebuild this list in parallel; with int TTL the helper
880	        // also spreads expiry across the fleet.
881	        return $this->cacheLock->rememberLocked(
882	            CacheKeyGenerator::siteBlocks($siteId, 'links'),
883	            (int) config('partna.cache.ttls.public_payload'),
884	            fn () => Block::query()
885	                ->where('site_id', $siteId)
886	                ->where('block_group', 'links')
887	                ->active()
